# PRIVATE build script - do NOT upload to GitHub. Run: python3 build_training.py
import os, json, base64, unicodedata, secrets
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives import hashes
NAMES = ["Demo Trainee"]  # replace with the 6 real full names
ITER = 150000
b = lambda x: base64.b64encode(x).decode()
def norm(s): return " ".join("".join(c for c in unicodedata.normalize("NFD", s) if not unicodedata.combining(c)).lower().split())
Q = lambda q, o, a, e: {"q": q, "o": o, "a": a, "e": e}
FLAG = '<p class="flag">Confirm with client before the live session.</p>'
S = [
{"t": "Welcome", "h": "<p>This training prepares you for the ADA Greek audio annotation project. You will learn to judge audio, cut it into segments, label speakers, transcribe Greek exactly as spoken, and add the special tags.</p><p><b>The standard is 98% accuracy or higher.</b> Every rule below exists to protect that number.</p><p>Plan about 3 hours. Your progress saves in this browser, so you can stop and continue. Work through the sections in order and answer every question.</p>", "q": []},
{"t": "How the task works", "h": "<p>Each audio file goes through five steps, always in this order:</p><ol><li>Decide whether each stretch of speech is valid or invalid.</li><li>Cut the valid speech into sentence segments.</li><li>Give each speaker an ID and mark gender.</li><li>Transcribe exactly what you hear.</li><li>Add the special tags the situation requires.</li></ol>", "q": [Q("What do you do first with a stretch of speech?", ["Transcribe it", "Decide if it is valid or invalid", "Add tags", "Mark the speaker gender"], 1, "Validity comes first, because invalid speech is not transcribed normally."), Q("Which step comes right after cutting segments?", ["Speaker ID and gender", "Tags", "Final check", "Validity"], 0, "Cut, then label speakers, then transcribe, then tag.")]},
{"t": "Valid or invalid speech", "h": "<p>A sentence is <b>invalid</b> when you cannot reliably transcribe the main speaker. The main causes:</p><ul><li>Two people talk at once at similar volume, with heavy overlap. (One or two overlapping words with a clear main speaker is fine.)</li><li>Unclear parts, so you cannot be sure of the content.</li><li>Background music, echo, or noise for most of the sentence, or strong noise hiding the speaker.</li><li>Dropped frames, clipping, echo, or abnormal energy.</li><li>Not normal live human speech: machine voices, synthesized voices, TV, phone calls, recordings played back.</li><li>Mostly non-Greek speech.</li><li>Sensitive content: political, religious, explicit, or violent.</li><li>A heavy accent.</li></ul>" + FLAG + "<p class='sm'>The guideline does not define what counts as a heavy accent.</p>", "q": [Q("A TV news voice plays in the background of the whole sentence. What is it?", ["Valid", "Invalid", "Valid with [N]", "Valid with [HM]"], 1, "Broadcast audio is not normal live speech."), Q("Two speakers overlap for one word, and the main speaker is clear. What do you do?", ["Mark invalid", "Transcribe it normally", "Delete the file", "Skip the speaker"], 1, "Minimal overlap with a clear main speaker is transcribed normally."), Q("Most of a sentence is in English. What is it?", ["Valid", "Invalid", "Valid with [N]", "Needs [PIL]"], 1, "Mostly non-native-language speech is invalid.")]},
{"t": "Cutting segments", "h": "<ul><li>Each segment is one meaningful sentence unit, at most <b>8 seconds</b>. The usual length is 5 to 6 seconds.</li><li>Put each boundary at the lowest point of the waveform.</li><li>Never put two speakers in one segment.</li><li>Leave 0.2 to 0.3 seconds of silence around the speech when it naturally exists. Never clip the speech. Shorten the margin if it would include a sudden noise.</li><li>Extract even a one-word reply. Merge it with a neighbouring sentence if possible.</li><li>A pause longer than 2 seconds splits the sentence into two. A pause under 2 seconds in a sentence of 8 seconds or less keeps it as one.</li><li>If a short pause under 2 seconds contains noise and splitting would break the meaning, do not split.</li></ul>", "q": [Q("What is the maximum length of a segment?", ["5 seconds", "8 seconds", "10 seconds", "No limit"], 1, "Segments never exceed 8 seconds."), Q("A speaker pauses for 2.5 seconds in the middle of a sentence. What do you do?", ["Keep one segment", "Split into two", "Mark invalid", "Add [N]"], 1, "Pauses longer than 2 seconds split the sentence."), Q("Someone answers with a single word. What do you do?", ["Ignore it", "Extract it, merging with a neighbour if possible", "Mark invalid", "Delete it"], 1, "Even one-word answers are extracted.")]},
{"t": "Speakers", "h": "<p>Give every different speaker in the file their own ID (for example O1, O2) and mark each speaker's gender. The same person keeps the same ID in the whole file. Never put two speakers in one segment.</p>", "q": [Q("A file has two people talking in turns. How many IDs do you need?", ["One", "Two", "Three", "None"], 1, "Each different speaker gets a separate ID.")]},
{"t": "Transcribing Greek", "h": "<p>Write exactly what is said: nothing added, nothing missing, nothing changed.</p><ul><li><b>Numbers:</b> write them in words, never digits. Say \"fifteen years old\": <span class='g'>Είμαι δεκαπέντε ετών.</span> Not <span class='g bad'>Είμαι 15 ετών.</span></li><li><b>Abbreviations:</b> write the full word as pronounced, not the short form.</li><li><b>Punctuation:</b> only comma, hyphen, period, exclamation mark, single quote and question mark are allowed. Spoken symbols are written as words.</li><li><b>Repeated words:</b> write every repetition.</li><li><b>Unfinished word:</b> add a hyphen and a space: <span class='g'>Θέλω να πάω στο σ- σχολείο.</span> An unfinished word at the very end of a sentence is left out.</li><li><b>Interjections:</b> transcribe them only if they carry meaning, such as a \"hmm\" that answers a question. Pure laughter is not annotated.</li><li><b>Profanity:</b> write it as spoken, without letter substitutes.</li></ul>" + FLAG + "<p class='sm'>Open points: the Greek question mark is \";\", but the guideline allows only the English question mark. The guideline also says nothing about Greek accent marks or how to write Greek numbers. Wait for the client's answer.</p>", "q": [Q("The speaker says a number. How do you write it?", ["Digits", "Words", "Either", "Skip it"], 1, "Numbers are always written in words."), Q("The speaker cuts a word off: \"στο σ- σχολείο\". Which is correct?", ["στο σ-σχολείο", "στο σ- σχολείο", "στο σχολείο", "στο σ σχολείο"], 1, "Hyphen at the end of the partial word, then a space."), Q("The speaker says a word twice. What do you write?", ["Once", "Both times", "Neither", "Mark invalid"], 1, "All repeated words are transcribed."), Q("Which interjection is transcribed?", ["Unconscious humming", "A \"hmm\" that answers a question", "Pure laughter", "A cough"], 1, "Interjections with meaning are annotated.")]},
{"t": "Special tags", "h": "<table><tr><th>Tag</th><th>Use</th></tr><tr><td>[N]</td><td>The sentence has noise. Put at the end of the sentence. Do not name the noise type.</td></tr><tr><td>[HM]</td><td>The speaker raps. Put at the end of the sentence.</td></tr><tr><td>[OVERLAP/] [/OVERLAP]</td><td>Surround the overlapped words. Transcribe only the clear speaker.</td></tr><tr><td>[IVS]</td><td>Invalid human speech longer than 0.5 seconds: heavy overlap, dropped frames, clipping, echo, singing or strained voice, non-target language, unreadable words.</td></tr><tr><td>[OIVS]</td><td>Recorded or broadcast voices longer than 0.5 seconds: TV, radio, ads, music with vocals.</td></tr><tr><td>[PIL]</td><td>Private information is spoken: address, phone number, ID, bank card, social security or passport number.</td></tr></table><p>Opening and closing tags must match, with the same capital letters and matching brackets. A missing tag counts as an error.</p>" + FLAG + "<p class='sm'>The guideline is unclear on when to use the overlap tags and when to use [IVS].</p>", "q": [Q("A speaker reads out a phone number. What tag?", ["[N]", "[PIL]", "[IVS]", "[HM]"], 1, "Phone numbers are private information."), Q("A sentence has light background noise but is clear. What tag?", ["[N] at the end", "[IVS]", "[OIVS]", "None"], 0, "Noise in a valid sentence gets [N] at the end."), Q("A TV advert fills the segment. What tag?", ["[N]", "[OIVS]", "[PIL]", "[HM]"], 1, "Recorded or broadcast voices use [OIVS].")]},
{"t": "Practice", "h": "<p>Mixed cases. Take your time and decide as you would on the job.</p>", "q": [Q("A clear 6-second sentence with a short car horn. What do you do?", ["Mark invalid", "Transcribe and add [N] at the end", "Cut into two", "Add [IVS]"], 1, "The speaker is clear, so it is valid with [N]."), Q("A caller shares a bank card number. What do you do?", ["Transcribe it as digits", "Write the number in words and add [PIL]", "Ignore the tag", "Delete the file"], 1, "Numbers are in words, and private data gets [PIL]. Ask your lead if the segment should be dropped."), Q("A 10-second sentence has no long pauses. What do you do?", ["Keep it whole", "Split into shorter segments of 8 seconds or less", "Mark invalid", "Add [N]"], 1, "Segments never exceed 8 seconds.")]},
{"t": "Final check", "h": "<p>Before you start the live work, confirm each point:</p><ul class='chk'><li>I know the five steps in order.</li><li>I can tell valid from invalid speech.</li><li>I cut segments at 8 seconds or less and never mix speakers.</li><li>I write numbers in words and repeat repeated words.</li><li>I know all six tags and always close the pairs.</li><li>I know the target is 98% accuracy.</li><li>I will not share these materials.</li></ul>", "q": []},
]
K = os.urandom(32); iv = os.urandom(12)
payload = b(iv) + "." + b(AESGCM(K).encrypt(iv, json.dumps(S, ensure_ascii=False).encode(), None))
A = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; users = []; lines = []
for n in NAMES:
    code = "-".join("".join(secrets.choice(A) for _ in range(4)) for _ in range(3))
    salt = os.urandom(16); wiv = os.urandom(12)
    key = PBKDF2HMAC(hashes.SHA256(), 32, salt, ITER).derive((norm(n) + "|" + code.replace("-", "")).encode())
    users.append([b(salt), b(wiv), b(AESGCM(key).encrypt(wiv, K, None))]); lines.append(f"{n}\t{code}")
open("codes_PRIVATE.txt", "w").write("\n".join(lines))
html = open("template.html").read().replace("__P__", payload).replace("__U__", json.dumps(users)).replace("__I__", str(ITER))
open("index.html", "w").write(html)
print("\n".join(lines))
